function pad(n){var s=String(n);while(s.length<6)s='0'+s;return s;}
var PREFIX='JAH-ENERSYS-';
var SRC='public';
var RECORD_KIND='energy system record';
var ANGLES=['overview','detailed','examples','faq','history','applications'];
var TOPICS=[{"title":"Energy Systems Overview","brief":"Energy systems convert, move, and use energy — from power plants to the grid to your home.","points":["Primary sources: fossil, nuclear, renewables.","Conversion to electricity, heat, or fuels.","The grid delivers electricity instantly on demand.","Efficiency and storage shape the whole system."],"examples":["A city's electricity from plants to outlets.","A home with solar, battery, and EV."],"history":["Edison's grid (1882) to today's system.","Now transforming to clean energy."],"uses":["Powering civilization.","Climate strategy.","Engineering careers."],"qa":[["What is an energy system?","Everything from source to end use."],["Why does it matter?","Energy underpins the economy and climate."],["What's changing?","Decarbonization, decentralization, digitalization."]]},{"title":"Electricity Generation","brief":"Electricity generation converts primary energy to power — spinning turbines or capturing photons.","points":["Thermal: heat makes steam spins turbines.","Hydro, wind: mechanical to electrical directly.","Solar PV: light to electricity, no moving parts.","Capacity factor: actual vs maximum output."],"examples":["A combined-cycle gas plant.","A wind farm's turbines."],"history":["Dynamos (1870s) to gigawatt plants.","Mix shifting to renewables."],"uses":["The power supply.","Investment decisions.","Grid planning."],"qa":[["Which generation is cheapest?","New wind/solar usually win on LCOE now."],["What is capacity factor?","Actual output ÷ maximum — solar ~20%, nuclear ~90%."],["Baseload vs peaker?","Always-on vs on-demand plants."]]},{"title":"Coal Power","brief":"Coal powered industrialization — now declining as cleaner sources outcompete it.","points":["Burns coal for steam; ~33% efficient.","Major CO2 and air-pollution source.","Retirements accelerating worldwide.","CCS could theoretically clean it — rarely economic."],"examples":["A retiring coal plant replaced by wind.","China and India's remaining coal fleets."],"history":["Watt's engine to global dominance (1900s).","Peak coal power passing."],"uses":["Historical understanding.","Transition planning.","Just-transition policy."],"qa":[["Is coal dead?","Declining fast in most regions; lingering in some."],["What replaces it?","Wind, solar, gas, storage — in combination."],["Can coal be clean?","CCS exists but is expensive and rare."]]},{"title":"Natural Gas Power","brief":"Natural gas is the flexible fossil fuel — bridging to renewables, with methane concerns.","points":["Combined-cycle plants reach 60% efficiency.","Fast-ramping complements wind and solar.","Methane leaks undermine climate benefits.","Price volatility is the economic risk."],"examples":["A CCGT plant balancing renewables.","The US shale gas boom."],"history":["Rise since the 1990s.","Now the transition fuel debate."],"uses":["Grid flexibility.","Heating and industry.","The bridge-fuel question."],"qa":[["Is gas clean?","Cleaner than coal, but still fossil — methane matters."],["Bridge to what?","To renewables+storage, say proponents; a trap, say critics."],["What about hydrogen blending?","Possible in limits; green hydrogen is the goal."]]},{"title":"Nuclear Power","brief":"Nuclear fission delivers steady carbon-free power — dense energy with waste and cost challenges.","points":["Fission splits atoms, heating water to steam.","Capacity factors ~90% — the reliability champion.","Waste stays hazardous for millennia; volumes are small.","New plants are expensive in the West; cheaper in Asia."],"examples":["France's 70% nuclear grid.","A US plant's 18-month refueling cycle."],"history":["1950s debut; scale-up 1970s-80s.","Stalled West, growing East."],"uses":["Carbon-free baseload.","Grid stability.","The nuclear debate."],"qa":[["Is nuclear safe?","Statistically among the safest energy sources."],["What about waste?","Small volumes; geological disposal is the technical answer."],["Why so expensive?","Construction complexity and regulation in the West."]]},{"title":"Hydropower","brief":"Hydropower is the original renewable — dams and run-of-river turning water into electricity.","points":["Largest renewable electricity source globally.","Dams store energy; run-of-river follows flow.","Pumped hydro is the biggest storage too.","Environmental costs: ecosystems, displacement, methane."],"examples":["Three Gorges: the world's largest plant.","Norway's hydro-dominated grid."],"history":["Early electric power (1880s).","Big-dam era mid-1900s."],"uses":["Renewable baseload.","Grid storage via pumped hydro.","Developing-world electrification."],"qa":[["Is hydro green?","Low-carbon, but with real ecological costs."],["Any room to grow?","Some — mostly small hydro and upgrades now."],["Drought risk?","Yes — climate change threatens output."]]},{"title":"Solar Photovoltaic (PV)","brief":"Solar PV turns sunlight directly into electricity — now the cheapest new power in most places.","points":["Silicon cells; ~20-25% efficient commercial.","Costs fell 90%+ since 2010.","Rooftop to utility-scale.","Inverters convert DC to grid AC."],"examples":["A rooftop system cutting bills.","A gigawatt solar farm."],"history":["Bell Labs (1954); space first.","Grid parity (2010s)."],"uses":["Clean electricity everywhere.","Energy access.","The growth engine."],"qa":[["How much roof do I need?","Roughly 100 sq ft per kW."],["What about night?","Net metering, batteries, or the grid."],["Do panels degrade?","~0.5% yearly — 25-year warranties standard."]]},{"title":"Wind Power","brief":"Wind turbines harvest the atmosphere — among the cheapest and fastest-growing power sources.","points":["Bigger turbines, taller towers: more, steadier wind.","Capacity factors 35-50% for good sites.","Onshore cheap; offshore stronger and steadier.","Grid integration is well-understood."],"examples":["Texas wind farms.","North Sea offshore arrays."],"history":["Modern turbines (1980s); scale-up (2000s+).","Now mainstream."],"uses":["Clean electricity.","Rural income.","Corporate procurement."],"qa":[["Do turbines kill birds?","Some — far fewer than cats or buildings; siting matters."],["What about when wind stops?","Geographic diversity plus storage and backup."],["Are they noisy?","Modern setbacks make them quiet neighbors."]]},{"title":"Geothermal Energy","brief":"Geothermal taps Earth's heat — steady, baseload renewable where geology allows.","points":["Volcanic regions: easy steam.","Enhanced geothermal (EGS): fracking-like techniques expand reach.","Heat pumps use shallow ground anywhere.","Capacity factors ~90%."],"examples":["Iceland's geothermal grid.","A home geothermal heat pump."],"history":["Larderello (1904) first plant.","EGS pilots (2020s) expanding."],"uses":["Baseload renewables.","Heating and cooling.","The steady contributor."],"qa":[["Where does it work?","Volcanic zones easily; EGS expanding reach."],["Are heat pumps geothermal?","Shallow-ground — efficient everywhere."],["Is EGS safe?","Induced seismicity is managed carefully."]]},{"title":"Hydrogen Energy","brief":"Hydrogen is an energy carrier — clean at use, with production method deciding its climate value.","points":["Green: electrolyzed with renewables; grey: from gas.","Uses: industry, heavy transport, storage.","Hard to transport and store — tiny molecule.","Economics challenging; niche uses first."],"examples":["Green steel pilots.","Hydrogen buses."],"history":["Hype cycles since the 1970s.","Current wave focused on hard sectors."],"uses":["Industrial decarbonization.","Long-duration storage.","Heavy transport."],"qa":[["Is hydrogen the future?","For some sectors, yes; for cars/heating, probably not."],["Why not everywhere?","Efficiency losses favor direct electrification."],["What color matters?","Green (clean) vs grey/blue — production decides."]]},{"title":"Energy Storage Overview","brief":"Storage decouples when energy is made from when it's used — the key to renewable grids.","points":["Short-duration (batteries) vs long-duration (hydrogen, pumped hydro).","Power (kW) vs energy (kWh) are different specs.","Costs falling fast for lithium-ion.","Every grid needs some; high-renewable grids need lots."],"examples":["A home battery riding through an outage.","Grid batteries firming solar output."],"history":["Pumped hydro dominated for a century.","Battery era (2010s+)."],"uses":["Renewable integration.","Reliability.","The growth market."],"qa":[["How much storage do we need?","Depends on renewable share — hours to days typically modeled."],["Batteries or pumped hydro?","Batteries for fast response; pumped hydro for bulk."],["Is storage economic?","Increasingly — value stacking helps."]]},{"title":"Lithium-Ion Grid Batteries","brief":"Grid-scale lithium-ion stores hours of energy — firming renewables and selling grid services.","points":["4-hour duration is the current sweet spot.","Revenue: energy arbitrage plus frequency services.","Costs fell ~90% in a decade.","Safety: thermal runaway managed by design."],"examples":["Moss Landing's giant battery.","A solar-plus-storage plant."],"history":["Hornsdale (2017) proved the model.","Explosive growth since."],"uses":["Renewable firming.","Peak shaving.","Grid services."],"qa":[["Are grid batteries safe?","Designed with fire suppression; incidents are rare."],["How long do they last?","10-15 years with augmentation."],["What about recycling?","Growing industry; regulations emerging."]]},{"title":"Pumped Hydro Storage","brief":"Pumped hydro is the giant of storage — water uphill when cheap, downhill when needed.","points":["~95% of global storage capacity.","Round-trip efficiency 70-85%.","Needs the right geography.","Decades-long asset life."],"examples":["Bath County: the world's largest.","Alpine pumped plants."],"history":["1890s origins; built out mid-1900s.","Still the backbone."],"uses":["Bulk energy shifting.","Grid stability.","The proven giant."],"qa":[["Why not build more?","Geography and permitting limit sites."],["Is it efficient?","Good enough at scale."],["Environmental impact?","Reservoirs have footprints — managed."]]},{"title":"The Power Grid","brief":"The grid is the largest machine ever built — balancing supply and demand every second.","points":["Generation, transmission, distribution, customers.","Frequency (60/50Hz) signals balance.","Operators dispatch plants economically.","Reliability standards are strict."],"examples":["A control room balancing a region.","The Eastern Interconnection's scale."],"history":["Edison to interconnected grids (1900s).","Now digitizing."],"uses":["Modern life.","The platform for clean energy.","Emergency planning and resilience."],"qa":[["How does it stay balanced?","Markets and operators match supply to demand continuously."],["What happens when it fails?","Cascading blackouts — rare but serious."],["Who runs it?","Utilities and ISOs/RTOs."]]},{"title":"Smart Grid Technology","brief":"Smart grids add sensing and control — visibility from plant to plug.","points":["Smart meters: interval data and time-varying rates.","Distribution automation: self-healing feeders.","DERMS manages distributed resources.","Cybersecurity is critical."],"examples":["Automated fault isolation.","Time-of-use EV charging."],"history":["Stimulus-funded rollout (2010s).","Ongoing."],"uses":["Reliability.","Renewable integration.","Customer empowerment."],"qa":[["Will it lower bills?","Efficiency and time-varying rates help engaged users."],["Is my data safe?","Privacy rules govern usage."],["What about hackers?","Grid cybersecurity is a top priority."]]},{"title":"Microgrids","brief":"Microgrids are local grids that can island — keeping power on when the big grid fails.","points":["Solar + storage + controls, typically.","Seamless islanding and reconnection.","Campuses, hospitals, communities.","Resilience is the value proposition."],"examples":["A hospital riding through an outage.","A remote village's solar microgrid."],"history":["Military bases pioneered; spreading.","Costs falling."],"uses":["Resilience.","Remote electrification.","Community energy."],"qa":[["How much do they cost?","Varies widely; resilience value justifies."],["Can they sell to the grid?","Often yes — services and energy."],["Do I need one?","If outages cost you dearly."]]},{"title":"Demand Response","brief":"Demand response pays users to shift usage — flexibility as a grid resource.","points":["Price signals or direct control.","Water heaters, EVs, and AC are ideal loads.","Aggregators pool small resources.","Cheaper than peaker plants."],"examples":["A utility cycling ACs on peak days.","An EV charging when wind is strong."],"history":["Early programs (1980s); smart tech scaled them.","Now mainstream."],"uses":["Peak reduction.","Renewable integration.","Customer savings."],"qa":[["Does it inconvenience me?","Well-designed, barely noticeable."],["How do I participate?","Utility programs or aggregators."],["Is it effective?","Yes — gigawatts of flexible load."]]},{"title":"Grid Stability and Frequency","brief":"Frequency is the grid's heartbeat — 60Hz means balanced; deviations mean trouble.","points":["Inertia from spinning machines resists change.","Inverters can synthesize inertia (grid-forming).","Frequency response services act in seconds.","Blackouts cascade from instability."],"examples":["A generator trip and the frequency dip.","Batteries providing fast frequency response."],"history":["Always fundamental; renewables change the mix.","Grid-forming inverters emerging."],"uses":["Reliability engineering.","Renewable integration.","The physics of the grid."],"qa":[["Why 60Hz?","Historical standard — 50Hz elsewhere."],["Do renewables hurt stability?","Managed with inverters and services, no."],["What is inertia?","Rotating mass resisting frequency change."]]},{"title":"Blackouts and Grid Reliability","brief":"Blackouts range from local faults to cascading collapses — reliability is engineered, not accidental.","points":["N-1 criterion: survive any single failure.","Cascades: overloaded lines tripping in sequence.","Vegetation management prevents many outages.","Resilience: withstanding extremes."],"examples":["The 2003 Northeast blackout.","Texas 2021: extreme cold."],"history":["Standards tightened after each major event.","Climate raising the bar."],"uses":["Keeping lights on.","Emergency planning.","Investment priorities."],"qa":[["How reliable is the grid?","Very — 99.9%+ typical in developed grids."],["What causes most outages?","Weather and trees, locally."],["Can we prevent all blackouts?","No — but reduce frequency and impact."]]},{"title":"Levelized Cost of Energy (LCOE)","brief":"LCOE compares generation costs per unit — the scoreboard of the energy transition.","points":["Lifetime costs ÷ lifetime energy.","Wind/solar now cheapest new-build in most markets.","Excludes grid integration costs.","Falling curves drove the transition."],"examples":["Lazard's annual LCOE reports.","Auction prices for solar."],"history":["Concept old; prominence with renewables.","Now the headline metric."],"uses":["Investment decisions.","Policy design.","Understanding the transition."],"qa":[["Is LCOE the whole story?","No — value (when power is made) matters too."],["Why did renewables get cheap?","Learning curves and scale."],["What about storage costs?","LCOS is the storage analog."]]},{"title":"Renewable Energy Integration","brief":"Integrating variable renewables is the central grid challenge — solved with flexibility, not just backup.","points":["Forecasting, geographic diversity, and flexible demand.","Storage for hours; transmission for weather systems.","Curtailment as a safety valve.","High-renewable grids already operate."],"examples":["Denmark's wind-powered days.","South Australia's renewable records."],"history":["Niche to mainstream (2000s-2020s).","Now the core question."],"uses":["Decarbonization.","Grid planning.","The transition playbook."],"qa":[["Can we run on 100% renewables?","Studies say yes with the right mix."],["What about dunkelflaute?","Diversity, storage, and firm resources cover lulls."],["Is it expensive?","Integration costs are real but manageable."]]},{"title":"Net Metering and Rooftop Solar","brief":"Net metering credits rooftop solar owners — the policy that launched a million roofs.","points":["Spin the meter backward, conceptually.","Reforms toward net billing reflect grid costs.","Pairing with batteries maximizes value.","Renters and low-income need inclusive models."],"examples":["A homeowner's bill near zero.","Community solar for renters."],"history":["1970s origins; boom 2010s.","Evolving policies."],"uses":["Distributed clean energy.","Consumer empowerment.","Equity questions."],"qa":[["Is rooftop solar worth it?","Usually yes where sun and rates align."],["What are the policy fights?","Cost shifts vs grid benefits."],["Batteries too?","Increasingly the smart pairing."]]},{"title":"Virtual Power Plants","brief":"VPPs aggregate distributed resources — home batteries, EVs, thermostats — into grid-scale power.","points":["Software orchestrates thousands of devices.","Sells capacity and services to grids.","Pays participants.","The distributed alternative to peaker plants."],"examples":["Tesla's South Australia VPP.","A utility's thermostat fleet."],"history":["Concept old; software made it real (2010s+).","Scaling now."],"uses":["Grid flexibility.","Consumer income.","Peaker replacement."],"qa":[["How do I join?","Utility or aggregator programs."],["Do I lose control?","Good programs preserve comfort bounds."],["Is it profitable?","Modest payments now; growing."]]},{"title":"Electric Vehicles and the Grid","brief":"EVs are big new loads — and flexible ones, if charging is managed.","points":["Unmanaged charging stresses peaks.","Smart charging aligns with renewables.","V2G: cars as grid batteries (emerging).","Overall grid impact is manageable."],"examples":["Overnight charging on wind power.","A V2G pilot powering homes."],"history":["Early concern; managed solutions emerging.","Standards developing."],"uses":["Transport decarbonization.","Grid flexibility.","The load of the future."],"qa":[["Will EVs crash the grid?","No — with managed charging."],["What is V2G?","Vehicle-to-grid: cars supporting the grid."],["When should I charge?","Overnight or when renewables are abundant."]]},{"title":"Building Energy Systems (HVAC)","brief":"Buildings use ~40% of energy — HVAC and envelopes are the battleground.","points":["Heat pumps: 3-4x efficient heating.","Envelopes: insulation and air sealing.","Smart thermostats optimize.","Codes ratchet efficiency up."],"examples":["A heat-pump retrofit halving bills.","A net-zero office."],"history":["Efficiency gains for decades.","Electrification wave now."],"uses":["Comfort and bills.","Climate goals.","The built environment."],"qa":[["Heat pump or furnace?","Heat pump in most climates now."],["What saves most?","Air sealing and insulation first."],["Are smart thermostats worth it?","Yes — modest savings, real convenience."]]},{"title":"Combined Heat and Power (CHP)","brief":"CHP captures waste heat — doubling fuel efficiency where heat and power are both needed.","points":["80%+ total efficiency vs ~50% separate.","Hospitals, campuses, industry.","Micro-CHP for buildings (niche).","Fuel cells are the clean version."],"examples":["A hospital's CHP plant.","District energy systems."],"history":["Industrial staple for a century.","Clean variants growing."],"uses":["Efficiency.","Resilience.","Industrial decarbonization."],"qa":[["Is CHP green?","Efficient, but still burns fuel — green with biogas/hydrogen."],["Where does it fit?","Steady heat + power loads."],["What about fuel cells?","Quiet, clean CHP for buildings."]]},{"title":"Energy Efficiency","brief":"Efficiency is the first fuel — cheaper than supply, cutting bills and emissions.","points":["LEDs, heat pumps, better motors.","Standards and labels drive markets.","Rebound effects are real but partial.","Negawatts: saved energy as resource."],"examples":["LED lighting's global savings.","Appliance standards' quiet gains."],"history":["1970s oil shocks launched it.","Continuous progress."],"uses":["Bills and climate.","Energy security.","The cheapest clean energy."],"qa":[["Does efficiency just lead to more use?","Some rebound, but net savings dominate."],["What should I do first?","Audit, then the big loads."],["Is it enough alone?","No — needed alongside clean supply."]]},{"title":"Energy Audits","brief":"Audits find waste — systematic assessments of where energy goes.","points":["Walk-through to investment-grade.","Blower doors find leaks; thermal cameras see them.","Benchmarking against peers.","Implementation is the hard part."],"examples":["A home audit finding attic bypasses.","An industrial audit saving millions."],"history":["Standard practice for decades.","Now digitized."],"uses":["Saving money.","Prioritizing retrofits.","Compliance."],"qa":[["Should I get an audit?","Yes before major retrofits."],["What does it cost?","Hundreds for homes; more for industry — often subsidized."],["Then what?","Do the cost-effective measures."]]},{"title":"Carbon Capture and Storage (CCS)","brief":"CCS captures CO2 from plants or air — a tool for hard sectors, not a fossil free pass.","points":["Post-combustion capture from flue gas.","Storage in geological formations.","DAC: direct air capture, expensive.","Costs and energy penalties are high."],"examples":["Norway's Sleipner project.","DAC plants in Iceland."],"history":["1990s pilots; slow scale-up.","Policy support growing."],"uses":["Hard-to-abate industry.","Carbon removal.","The debated tool."],"qa":[["Does CCS work?","Technically yes; economically challenged."],["Excuse to keep burning?","Critics say so; proponents target hard sectors."],["What about DAC?","Needed for removal, but costly."]]},{"title":"Nuclear Fusion","brief":"Fusion promises abundant clean energy — the physics works; engineering at scale is the quest.","points":["Fusing light atoms releases energy.","NIF achieved ignition (2022).","Tokamaks (ITER) and private approaches.","Timeline: decades, optimists say sooner."],"examples":["NIF's ignition milestone.","Private fusion startups."],"history":["1950s dreams; steady progress.","Private investment surge (2020s)."],"uses":["The long-term dream.","Research careers.","Abundant energy hopes."],"qa":[["When will fusion power the grid?","Decades — plan without it."],["Is it safe?","No meltdown risk; tritium handled."],["Why invest?","The prize is civilization-scale clean energy."]]},{"title":"Small Modular Reactors (SMRs)","brief":"SMRs shrink nuclear plants — factory-built, potentially cheaper and more flexible.","points":["Modules under 300MW; factory fabrication.","Passive safety features.","Suits small grids and industry.","First deployments in the 2020s-30s."],"examples":["NuScale's design certification.","Russia's floating SMR."],"history":["Naval reactors proved small works.","Commercial SMRs emerging."],"uses":["Clean firm power.","Industrial heat.","The nuclear hope."],"qa":[["Are SMRs cheaper?","Promised via factory production — unproven at scale."],["When available?","Late 2020s-2030s for first units."],["Waste issues?","Same as large reactors, smaller volumes."]]},{"title":"Offshore Wind","brief":"Offshore wind harvests stronger, steadier winds — the coming giant of clean power.","points":["Capacity factors 50%+.","Fixed and floating foundations.","Transmission via subsea cables.","Costs falling fast."],"examples":["UK's Hornsea farms.","US East Coast pipeline."],"history":["Denmark (1991) first; scale-up (2010s+).","Now major."],"uses":["Coastal clean power.","Jobs and ports.","The growth frontier."],"qa":[["Why offshore?","Better wind, less land conflict."],["What about hurricanes?","Designed for extremes."],["Floating vs fixed?","Fixed in shallow; floating opens deep water."]]},{"title":"Concentrated Solar Power (CSP)","brief":"CSP focuses sun for heat — with built-in thermal storage for after sunset.","points":["Mirrors heat fluid to drive turbines.","Molten-salt storage for hours.","Needs direct sun (deserts).","Niche vs PV's dominance."],"examples":["Morocco's Noor complex.","Ivanpah's towers."],"history":["1980s plants; revival 2000s.","Storage is the edge."],"uses":["Dispatchable solar.","Desert regions.","Industrial process heat."],"qa":[["CSP or PV?","PV usually wins now; CSP where storage matters."],["Does it work at night?","With thermal storage, yes."],["Bird issues?","Managed with deterrents."]]},{"title":"Biomass Energy","brief":"Biomass burns organic matter — renewable if regrown, with land-use caveats.","points":["Wood, crops, waste to heat/power.","Carbon-neutral in theory; accounting debated.","BECCS: biomass plus CCS for negative emissions.","Competes with food and forests."],"examples":["Scandinavian district heating.","Drax's biomass conversion."],"history":["Oldest fuel; modern plants.","Debated sustainability."],"uses":["Dispatchable renewable.","Waste utilization.","The contested renewable."],"qa":[["Is biomass green?","Depends on sourcing — genuinely debated."],["BECCS viable?","Models rely on it; scale unproven."],["Better uses?","Materials and chemicals over burning."]]},{"title":"Tidal and Wave Energy","brief":"Oceans hold vast energy — tides predictable, waves powerful, both early-stage.","points":["Tidal: predictable but site-limited.","Wave: huge resource, harsh environment.","Early commercial projects.","Niche in the mix."],"examples":["La Rance tidal plant (1966).","Orkney wave test sites."],"history":["Decades of R&D.","Slow commercialization."],"uses":["Coastal power.","Predictable renewables.","The long shot."],"qa":[["Will it scale?","Tidal in spots; wave still proving."],["Why so slow?","Harsh marine environment costs."],["Environmental impact?","Studied carefully at test sites."]]},{"title":"Flow Batteries","brief":"Flow batteries store energy in liquid electrolytes — scaling power and energy independently.","points":["Vanadium redox is the leader.","Tanks size energy; stacks size power.","Long duration, long life.","Lower energy density than lithium."],"examples":["A vanadium system for a microgrid.","Long-duration pilots."],"history":["NASA origins (1970s); commercial (2010s+).","Growing."],"uses":["Long-duration storage.","Microgrids.","The alternative chemistry."],"qa":[["Flow or lithium?","Flow for long duration and life."],["Are they safe?","Aqueous electrolytes are benign."],["Cost competitive?","At long durations, increasingly."]]},{"title":"Thermal Energy Storage","brief":"Storing heat (or cold) is cheap — for buildings, industry, and CSP.","points":["Molten salt, hot water, ice, phase-change.","Round-trip via heat engines or direct use.","Cheapest storage per kWh.","Limited to thermal applications."],"examples":["Ice storage cooling buildings.","Molten salt at solar plants."],"history":["Ancient (ice houses) to modern.","Growing with renewables."],"uses":["Building HVAC.","Industrial heat.","CSP plants."],"qa":[["Why so cheap?","Heat is easy to store."],["Can it make electricity?","Via heat engines — with losses."],["Home applications?","Hot water tanks and ice storage."]]},{"title":"District Heating and Cooling","brief":"District systems pipe heat to whole neighborhoods — efficient at urban scale.","points":["Central plants serve many buildings.","Waste heat and renewables feed in.","Common in Scandinavia, China.","5th-generation: ambient loops."],"examples":["Copenhagen's district heating.","A campus chilled-water loop."],"history":["1880s origins; modern networks.","Decarbonizing now."],"uses":["Urban efficiency.","Waste-heat use.","The city-scale solution."],"qa":[["Is it efficient?","Very at density."],["Can it decarbonize?","With heat pumps and waste heat, yes."],["Why not everywhere?","Needs density and upfront investment."]]},{"title":"Industrial Energy Systems","brief":"Industry uses a third of energy — efficiency and electrification are the levers.","points":["Heat dominates industrial energy.","Electrification: heat pumps, e-boilers, arc furnaces.","Hydrogen for high-heat processes.","Energy management systems optimize."],"examples":["An electric arc furnace.","A paper mill's efficiency overhaul."],"history":["Efficiency gains for decades.","Deep decarbonization now."],"uses":["Competitiveness.","Climate goals.","The hard sector."],"qa":[["Can industry electrify?","Much of it — heat pumps and furnaces."],["What about steel/cement?","Hydrogen, CCS, and new processes."],["Is it economic?","With carbon prices, increasingly."]]},{"title":"Energy Markets","brief":"Electricity markets price power every 5 minutes — complex auctions keeping the grid economic.","points":["Day-ahead and real-time markets.","Capacity markets pay for availability.","Ancillary services price flexibility.","Design shapes investment."],"examples":["PJM's massive market.","Texas's energy-only design."],"history":["Deregulation (1990s+).","Evolving for renewables."],"uses":["Efficient dispatch.","Investment signals.","Consumer prices."],"qa":[["Do markets work?","Mostly — design details matter enormously."],["What about Texas 2021?","Energy-only design under extreme stress."],["How do renewables fit?","Zero-marginal-cost bids reshape prices."]]},{"title":"Decentralized Energy","brief":"Energy is decentralizing — rooftop solar, batteries, and EVs turning consumers into prosumers.","points":["DERs: distributed energy resources.","Coordination via aggregators and VPPs.","Regulation catching up.","Resilience and choice as drivers."],"examples":["A neighborhood solar+battery network.","Peer-to-peer trading pilots."],"history":["From central plants to edge resources.","Ongoing transformation."],"uses":["Consumer empowerment.","Resilience.","The grid's future shape."],"qa":[["Will the grid disappear?","No — it becomes the platform."],["Who manages it all?","DSOs, aggregators, and software."],["Is it fair?","Design tariffs carefully."]]},{"title":"Energy Access","brief":"A billion people lack electricity — access is development's prerequisite.","points":["Off-grid solar leading the charge.","Mini-grids for villages.","Productive uses multiply impact.","Finance is the barrier."],"examples":["Kenya's solar home systems.","A mini-grid powering a village."],"history":["Progress but gaps remain.","SDG7 targets universal access."],"uses":["Development.","Health and education.","The moral imperative."],"qa":[["How to electrify fastest?","Grid extension plus off-grid where economic."],["Is solar enough?","For many needs, yes — with storage."],["Who pays?","Blended finance and falling costs."]]},{"title":"The Energy Transition","brief":"The energy transition is the great infrastructure project — rewiring the world for clean energy.","points":["Electrify everything; clean the grid.","Tripling renewables by 2030 (COP28).","Investment in the trillions.","Justice: no one left behind."],"examples":["Countries phasing out coal.","EV adoption curves."],"history":["Underway, accelerating.","The defining project."],"uses":["Climate.","Jobs and growth.","Our future."],"qa":[["Is it happening fast enough?","Not yet — acceleration needed."],["What will it cost?","Trillions — but inaction costs more."],["Can I help?","Electrify, advocate, invest."]]},{"title":"Compressed Air Energy Storage","brief":"CAES stores energy as compressed air — underground caverns as batteries.","points":["Compress air off-peak; expand through turbines.","Salt caverns ideal.","Adiabatic designs improve efficiency.","Long-duration niche."],"examples":["Huntorf plant (1978).","New adiabatic pilots."],"history":["Decades old; few plants.","Renewed interest."],"uses":["Long-duration storage.","Grid balancing.","Renewable integration support."],"qa":[["Why so few?","Geology limits sites."],["Efficiency?","50-70%; adiabatic better."],["Future?","Niche but real."]]},{"title":"Flywheel Energy Storage","brief":"Flywheels store energy as spin — instant power for seconds to minutes.","points":["Carbon-fiber rotors in vacuum.","High power, low energy.","Frequency regulation specialty.","Long life, low maintenance."],"examples":["A data center's flywheel UPS.","Grid frequency pilots."],"history":["Ancient concept; modern materials.","Niche applications."],"uses":["Power quality.","UPS bridging.","Motorsport KERS heritage."],"qa":[["How long do they store?","Minutes — power, not energy."],["Are they safe?","Containment designed for failures."],["Where used?","Frequency response and UPS."]]},{"title":"Transmission Expansion","brief":"The grid needs more wires — transmission unlocks renewables and resilience.","points":["Renewables are far from loads.","HVDC for long distances.","Permitting is the bottleneck.","Pays for itself in savings."],"examples":["Plains wind to coastal cities.","Interconnectors between countries."],"history":["Build-out needed worldwide.","Policy catching up."],"uses":["Clean energy delivery.","Reliability.","The enabler."],"qa":[["Why not just build local?","Best resources are remote."],["What blocks it?","Permitting and cost allocation."],["HVDC or AC?","HVDC for long/undersea."]]},{"title":"Substations","brief":"Substations are the grid's switching yards — transforming voltage and routing power.","points":["Transformers, breakers, busbars.","Digital substations with IEC 61850.","Security: physical and cyber.","Maintenance keeps them reliable."],"examples":["A neighborhood substation.","A digital retrofit."],"history":["As old as grids.","Digitizing now."],"uses":["Grid operation.","Reliability.","The hidden infrastructure."],"qa":[["What happens inside?","Voltage transformation and switching."],["Why the humming?","Transformer magnetostriction."],["Are they targets?","Physical security matters — hence hardening."]]},{"title":"Green Steel and Industry","brief":"Heavy industry decarbonizes via hydrogen, electrification, and CCS — the hard frontier.","points":["Green steel: hydrogen direct reduction.","Electric arc furnaces with clean power.","Cement: new chemistries and CCS.","Green premiums falling."],"examples":["HYBRIT's fossil-free steel.","A green cement pilot."],"history":["Pilots now; scale this decade.","Policy driving."],"uses":["Deep decarbonization.","Industrial competitiveness.","Green premium markets."],"qa":[["Is green steel real?","Pilot scale now; commercial coming."],["Cost premium?","Falling; small share of end-product cost."],["What about cement?","Harder — CCS and new chemistries."]]},{"title":"The Future of Energy","brief":"Energy's future: abundant clean power, smart systems, and universal access.","points":["Solar + storage + wind dominate new build.","Electrification spreads.","Fusion as the long shot.","The transition accelerates."],"examples":["Terawatt-scale solar.","Universal clean access."],"history":["Being written now.","The stakes are civilizational."],"uses":["Climate.","Prosperity.","Careers."],"qa":[["What will 2050 look like?","Mostly clean, electrified, smarter."],["What should I do?","Learn, build, advocate."],["Reasons for hope?","Cost curves and deployment speed."]]},{"title":"Energy Policy and Regulation","brief":"Policy shapes energy — subsidies, standards, and carbon prices steering the transition.","points":["Subsidies launched wind and solar.","Carbon pricing internalizes climate costs.","Standards drive efficiency.","Permitting reform unlocks build-out."],"examples":["The US Inflation Reduction Act.","The EU's carbon border adjustment."],"history":["Oil shocks to climate policy.","Now central."],"uses":["The transition's pace.","Investment signals.","Equity."],"qa":[["What policy works best?","Portfolios: price carbon, support innovation, fix permitting."],["Do subsidies work?","Yes — solar's cost curve proves it."],["What slows the transition?","Permitting, grids, and politics."]]}, {"title":"The Continental Supergrid","brief":"A continental supergrid links entire continents with high-voltage direct-current lines, letting noon solar in one timezone power evening demand in another.","examples":["HVDC lines lose only about 3 percent per 1,000 kilometers, making intercontinental power trade technically feasible; China already operates ultra-high-voltage lines over 3,000 kilometers. The engineering is proven; the politics is the hard part."],"history":["The geopolitical prize is energy interdependence: a grid that shares power across borders makes energy wars as unthinkable as trade wars between deeply linked economies."],"points":["A continental supergrid links entire continents with high-voltage direct-current lines, letting noon solar in one timezone power evening demand in another.","HVDC lines lose only about 3 percent per 1,000 kilometers, making intercontinental power trade technically feasible; China already operates ultra-high-voltage lines over 3,000 kilometers. The engineering is proven; the politics is the hard part."]}, {"title":"Orbital Solar Power Stations","brief":"Space-based solar power collects sunlight in orbit, where it shines 24 hours a day, and beams it to Earth as microwaves.","examples":["The physics is sound: no night, no clouds, no seasons, and sunlight 40 percent stronger than at the surface. The challenges are launch cost, beam safety, and building kilometer-scale structures in orbit."],"history":["Recent cost drops in heavy launch have revived the concept; analysts now model orbital solar as competitive by the 2040s, which would make it the largest construction project in human history."],"points":["Space-based solar power collects sunlight in orbit, where it shines 24 hours a day, and beams it to Earth as microwaves.","The physics is sound: no night, no clouds, no seasons, and sunlight 40 percent stronger than at the surface. The challenges are launch cost, beam safety, and building kilometer-scale structures in orbit."]}, {"title":"Deep Geothermal: Drilling to the Mantle","brief":"Deep geothermal aims to drill 10 to 20 kilometers down, where rock is hot enough anywhere on Earth to generate power around the clock.","examples":["New drilling technologies, including millimeter-wave and plasma drilling, promise to bore through hard basement rock far cheaper than rotary drills. A single deep well could power a small city from anywhere."],"history":["The prize is baseload power with no geography lottery: unlike today's geothermal, which needs volcanic regions, deep geothermal works everywhere, making it potentially the most democratic energy source ever."],"points":["Deep geothermal aims to drill 10 to 20 kilometers down, where rock is hot enough anywhere on Earth to generate power around the clock.","New drilling technologies, including millimeter-wave and plasma drilling, promise to bore through hard basement rock far cheaper than rotary drills. A single deep well could power a small city from anywhere."]}, {"title":"The Hydrogen Backbone","brief":"A hydrogen backbone repurposes natural gas pipelines to carry green hydrogen from sunny and windy regions to industrial centers.","examples":["Hydrogen can be made by electrolyzing water with surplus renewable power, stored for months, and burned or fuel-celled on demand. Pipeline conversion requires new compressors and embrittlement-resistant linings."],"history":["The strategic role is seasonal storage: hydrogen is the only storage medium that plausibly covers a windless winter week for a whole country, which makes the backbone the grid's savings account."],"points":["A hydrogen backbone repurposes natural gas pipelines to carry green hydrogen from sunny and windy regions to industrial centers.","Hydrogen can be made by electrolyzing water with surplus renewable power, stored for months, and burned or fuel-celled on demand. Pipeline conversion requires new compressors and embrittlement-resistant linings."]}, {"title":"Tidal Lagoon Networks","brief":"Tidal lagoons impound coastal areas and generate power from the rise and fall of the tide, a lunar clockwork as predictable as any power source.","examples":["Unlike tidal stream turbines, lagoons work in shallow water with simple technology; the Swansea Bay proposal modeled 320 megawatts from a single lagoon. The tide's schedule is known centuries in advance."],"history":["The network vision strings lagoons along a coast so their staggered tides produce near-continuous power; the engineering is civil, the fuel is the moon, and the maintenance is mostly concrete."],"points":["Tidal lagoons impound coastal areas and generate power from the rise and fall of the tide, a lunar clockwork as predictable as any power source.","Unlike tidal stream turbines, lagoons work in shallow water with simple technology; the Swansea Bay proposal modeled 320 megawatts from a single lagoon. The tide's schedule is known centuries in advance."]}, {"title":"Small Modular Reactors in the Grid Mix","brief":"Small modular reactors promise factory-built nuclear power at 50 to 300 megawatts, sized for cities and industrial sites rather than gigawatt grids.","examples":["Factory construction should cut the cost overruns that plague big nuclear; passive safety designs shut down without power or operators. Several designs are in licensing across the US, UK, and Canada."],"history":["The grid role is firm clean power: SMRs fill the gaps that batteries cannot economically cover, and their waste heat can warm cities or desalinate water, doubling their value."],"points":["Small modular reactors promise factory-built nuclear power at 50 to 300 megawatts, sized for cities and industrial sites rather than gigawatt grids.","Factory construction should cut the cost overruns that plague big nuclear; passive safety designs shut down without power or operators. Several designs are in licensing across the US, UK, and Canada."]}, {"title":"The Global Wind Atlas Grid","brief":"A wind-optimized planetary grid would site turbines wherever the wind blows strongest and share the power globally, smoothing weather into baseload.","examples":["Wind resources are anti-correlated across continents: when Europe is calm, the American Midwest often blows. Statistical studies show intercontinental links cut wind's variability dramatically."],"history":["The implementation path starts regionally: North Sea, then transatlantic, then global, with each link making the next more valuable, a network effect for electrons."],"points":["A wind-optimized planetary grid would site turbines wherever the wind blows strongest and share the power globally, smoothing weather into baseload.","Wind resources are anti-correlated across continents: when Europe is calm, the American Midwest often blows. Statistical studies show intercontinental links cut wind's variability dramatically."]}, {"title":"Gravity Storage: The Mountain Battery","brief":"Gravity storage lifts massive weights when power is cheap and drops them to generate when power is dear, a mountain-scale battery with no chemistry.","examples":["Systems range from abandoned mine shafts with suspended weights to purpose-built towers; round-trip efficiency reaches 80 percent and the storage lasts indefinitely with no degradation."],"history":["The advantage is lifespan: a gravity battery works for a century with minimal maintenance, making it the grid's equivalent of a stone bridge in a world of wooden ones."],"points":["Gravity storage lifts massive weights when power is cheap and drops them to generate when power is dear, a mountain-scale battery with no chemistry.","Systems range from abandoned mine shafts with suspended weights to purpose-built towers; round-trip efficiency reaches 80 percent and the storage lasts indefinitely with no degradation."]}, {"title":"Algae Biofuel at Scale","brief":"Algae can produce 10 to 100 times more oil per acre than land crops, without competing for farmland, making it the most promising biofuel feedstock.","examples":["The biology is proven but the economics are brutal: dewatering and processing eat the energy gains. Current research focuses on strains that secrete fuel directly, skipping the harvest step."],"history":["The breakthrough scenario is wastewater algae: fuel grown while cleaning sewage, turning a cost center into a power plant, which changes the economics entirely."],"points":["Algae can produce 10 to 100 times more oil per acre than land crops, without competing for farmland, making it the most promising biofuel feedstock.","The biology is proven but the economics are brutal: dewatering and processing eat the energy gains. Current research focuses on strains that secrete fuel directly, skipping the harvest step."]}, {"title":"The Superconducting Grid","brief":"Superconducting transmission lines carry enormous power with zero resistance, potentially quintupling grid capacity in existing corridors.","examples":["High-temperature superconductors cooled with liquid nitrogen are already deployed in pilot projects in the US, Germany, and Korea. The challenge is cost and the cryogenic infrastructure."],"history":["The transformative use is urban: superconducting cables can feed a megacity through a single corridor, avoiding the land battles that stall conventional lines."],"points":["Superconducting transmission lines carry enormous power with zero resistance, potentially quintupling grid capacity in existing corridors.","High-temperature superconductors cooled with liquid nitrogen are already deployed in pilot projects in the US, Germany, and Korea. The challenge is cost and the cryogenic infrastructure."]}, {"title":"Ocean Thermal Energy Conversion","brief":"OTEC exploits the temperature difference between warm surface water and cold deep water in the tropics to generate continuous power.","examples":["A 20-degree Celsius difference drives a heat engine; the fuel is free and the output is baseload. Pilot plants in Hawaii and Japan have proven the concept at small scale."],"history":["OTEC's bonus products may matter more than the power: desalinated water, cold-water aquaculture, and air conditioning from deep seawater, making each plant a multi-utility."],"points":["OTEC exploits the temperature difference between warm surface water and cold deep water in the tropics to generate continuous power.","A 20-degree Celsius difference drives a heat engine; the fuel is free and the output is baseload. Pilot plants in Hawaii and Japan have proven the concept at small scale."]}, {"title":"The Demand Response Revolution","brief":"Demand response turns flexible loads, water heaters, EV chargers, industrial processes, into a virtual power plant that follows supply instead of fighting it.","examples":["Smart tariffs already shift gigawatts of load in some markets; the next step is automated negotiation where every device bids for power in real time. The grid becomes a market, not just a machine."],"history":["The endgame is a grid with no peaker plants: flexibility replaces generation, and the cheapest power plant is the one you never have to build."],"points":["Demand response turns flexible loads, water heaters, EV chargers, industrial processes, into a virtual power plant that follows supply instead of fighting it.","Smart tariffs already shift gigawatts of load in some markets; the next step is automated negotiation where every device bids for power in real time. The grid becomes a market, not just a machine."]}, {"title":"Perovskite Solar: The Printable Panel","brief":"Perovskite solar cells can be printed like newspaper and have rocketed from 3 to over 25 percent efficiency in a decade, the fastest progress in solar history.","examples":["Tandem perovskite-silicon cells promise over 30 percent efficiency at potentially lower cost than silicon alone. The remaining challenge is durability: perovskites degrade in moisture and heat."],"history":["If stability is solved, solar becomes a coating: windows, roofs, and even fabrics generate power, and the energy transition accelerates from infrastructure project to paint job."],"points":["Perovskite solar cells can be printed like newspaper and have rocketed from 3 to over 25 percent efficiency in a decade, the fastest progress in solar history.","Tandem perovskite-silicon cells promise over 30 percent efficiency at potentially lower cost than silicon alone. The remaining challenge is durability: perovskites degrade in moisture and heat."]}, {"title":"The Methane Pyrolysis Bridge","brief":"Methane pyrolysis splits natural gas into hydrogen and solid carbon with no CO2, offering a bridge from today's gas grid to a hydrogen future.","examples":["The solid carbon is valuable: carbon black, graphite, even diamond feedstocks, turning emissions into products. The process needs high temperatures but no oxygen, so nothing burns."],"history":["The bridge logic is political as much as technical: it gives gas-producing regions a path into the clean economy instead of a cliff, which may be what makes the transition actually happen."],"points":["Methane pyrolysis splits natural gas into hydrogen and solid carbon with no CO2, offering a bridge from today's gas grid to a hydrogen future.","The solid carbon is valuable: carbon black, graphite, even diamond feedstocks, turning emissions into products. The process needs high temperatures but no oxygen, so nothing burns."]}, {"title":"Grid-Forming Inverters","brief":"Grid-forming inverters let solar and wind farms provide the stability services that spinning turbines used to, keeping the grid's heartbeat steady.","examples":["Traditional grids rely on the physical inertia of spinning generators; inverter-based resources can synthesize inertia electronically and respond in milliseconds, faster than any turbine."],"history":["This is the control theory that makes 100 percent renewable grids possible: the grid of the future will be more stable than today's, because electronics out-react iron."],"points":["Grid-forming inverters let solar and wind farms provide the stability services that spinning turbines used to, keeping the grid's heartbeat steady.","Traditional grids rely on the physical inertia of spinning generators; inverter-based resources can synthesize inertia electronically and respond in milliseconds, faster than any turbine."]}];
function buildContent(t,angle){
  var title=t.title,brief=t.brief,pts=t.points,exs=t.examples,his=t.history,uses=t.uses,qa=t.qa;
  var summary,sections,key_facts,i,rest;
  if(angle==='overview'){
    summary=brief+' This overview covers the essentials of '+title+': what it is, why it matters, and where it is used.';
    sections=[{heading:'What it is',body:brief+' '+pts.slice(0,2).join(' ')},{heading:'Key points',body:pts.join(' ')},{heading:'Why it matters',body:uses.slice(0,2).join(' ')}];
    key_facts=pts;
  }else if(angle==='detailed'){
    rest=pts.slice(2);
    summary='A detailed examination of '+title+'. '+brief;
    sections=[{heading:'Core details',body:pts.slice(0,3).join(' ')},{heading:'Going deeper',body:rest.length?rest.join(' '):pts.join(' ')},{heading:'Background and context',body:his.slice(0,2).join(' ')},{heading:'Where it is used',body:uses.join(' ')}];
    key_facts=pts;
  }else if(angle==='examples'){
    summary='Illustrative examples of '+title+' in practice. '+brief;
    sections=[];for(i=0;i<exs.length;i++)sections.push({heading:'Example '+(i+1),body:exs[i]});
    key_facts=pts.slice(0,3);
  }else if(angle==='faq'){
    summary='Frequently asked questions about '+title+'. '+brief;
    sections=[];for(i=0;i<qa.length;i++)sections.push({heading:'Q: '+qa[i][0],body:'A: '+qa[i][1]});
    key_facts=pts.slice(0,3);
  }else if(angle==='history'){
    summary='The background and development of '+title+'. '+brief;
    sections=[];for(i=0;i<his.length;i++)sections.push({heading:'Milestone '+(i+1),body:his[i]});
    key_facts=pts.slice(0,3);
  }else{
    summary='Practical applications of '+title+'. '+brief;
    sections=[];for(i=0;i<uses.length;i++)sections.push({heading:'Application '+(i+1),body:uses[i]});
    key_facts=pts.slice(0,3);
  }
  return{summary:summary,sections:sections,key_facts:key_facts};
}
